void Solver::rephase() {
    rephases = 0;
    threshold *= 0.9;
    rephase_limit += 8192;

    // Update phases based on current state
    int phase_choice = rand() % 100;

    if (phase_choice < 50) {
        // Keep current phase for variables assigned in trail
        // Reset others to local_best
        for (int i = 1; i <= vars; i++) {
            if (value[i] != 0) {
                saved[i] = value[i];  // Keep current assignment
            } else {
                saved[i] = local_best[i];  // Use local best for unassigned
            }
        }
    } else if (phase_choice < 80) {
        // Mix: current value for assigned vars, random for others
        for (int i = 1; i <= vars; i++) {
            if (value[i] != 0) {
                saved[i] = value[i];
            } else {
                saved[i] = rand() % 2 ? 1 : -1;
            }
        }
    } else {
        // Inverse of local best
        for (int i = 1; i <= vars; i++) {
            saved[i] = -local_best[i];
        }
    }
}
